#!/usr/bin/env node
// scripts/tag-claims-kind.js — V3.1 one-off migration.
//
// Tags every claim in an existing run's STEP files with `kind`
// (metric|recommendation|benchmark) and, for metrics, a `collectionHint`.
// Writes to step JSONs only — never claims.json (that is regenerated by render).
// Idempotent: re-running produces the same result.
//
// Usage:  node scripts/tag-claims-kind.js output/<run-dir>
// Then:   node strategy/cli.js render        (re-ingests; kind/hint flow into claims.json)
//         node strategy/cli.js collect-plan <run-dir>
//
// The maps below are the agreed classification for the BotConversa run. Audit them:
// "metric" = a number that lives in the company's own systems and the agent should ask for.
// "recommendation" = our proposal/target. "benchmark" = public/market/derived fact.

const fs = require('fs');
const path = require('path');

const KIND = {
  // --- metric (15): internal numbers the agent collects from the client ---
  f01: 'metric', f02: 'metric', f03: 'metric', f04: 'metric', f05: 'metric',
  f06: 'metric', f07: 'metric', f08: 'metric', f09: 'metric', f10: 'metric',
  f11: 'metric', r01: 'metric', s01: 'metric', m01: 'metric', m05: 'metric',
  // --- recommendation (6): our proposals/targets, not asked of the client ---
  m03: 'recommendation', m04: 'recommendation',
  r02: 'recommendation', r03: 'recommendation', r04: 'recommendation', r06: 'recommendation',
  // --- benchmark (23): public/market/derived facts, confirmed by research ---
  c01: 'benchmark', c01b: 'benchmark', c02: 'benchmark', c03: 'benchmark', c04: 'benchmark',
  c05: 'benchmark', c06: 'benchmark', c07: 'benchmark', c08: 'benchmark', c09: 'benchmark',
  c10: 'benchmark', c11: 'benchmark', c12: 'benchmark', c13: 'benchmark', c14: 'benchmark',
  c15: 'benchmark', c16: 'benchmark', c17_noshowmath: 'benchmark', c18: 'benchmark', c19: 'benchmark',
  r05: 'benchmark', m02: 'benchmark', m06: 'benchmark',
};

const HINT = {
  f01: 'conversation analytics → % разговоров, дошедших до терминального узла без участия человека; аккаунты ≥30 conv/мес, 30-дн rolling (нужны terminal-state события)',
  f02: 'product analytics → уникальные аккаунты с ≥1 bot-resolved разговором за последние 7 дней',
  f03: 'onboarding-воронка → медиана дней от регистрации до первого опубликованного флоу с ≥1 реальным разговором',
  f04: 'flow-телеметрия / error logs → % разговоров в unhandled state, no-match intent или API timeout',
  f05: 'биллинг → отменённые платящие аккаунты за месяц ÷ платящие на начало месяца (logo churn, не revenue churn)',
  f06: 'биллинг/финансы → текущий MRR и число активных платящих аккаунтов',
  f07: 'product analytics → % новых регистраций с живым флоу за 14 дней (когорта по неделе регистрации)',
  f08: 'product analytics → медиана входящих разговоров на активный платящий аккаунт в месяц',
  f09: 'CRM / теги аккаунтов → % платящих в beauty/clinics/pet shops против прочих вертикалей',
  f10: 'booking-flow аналитика → % booking-разговоров с подтверждённой записью (нужны flow-completion события)',
  f11: 'flow-аналитика → % разговоров с эскалацией на человека (нужны escalation-trigger события)',
  r01: 'product data → % платящих аккаунтов ровно с одним опубликованным активным флоу',
  s01: 'CRM / конфиг аккаунта → % платящих аккаунтов с ≥2 операторами на эскалациях',
  m01: 'внутренний P&L → месячный opex: команда + инфра + фиксированные Meta-косты, без variable pass-through',
  m05: 'их Meta-биллинг → фактическая стоимость pass-through на аккаунт/мес. Публичный ориентир: ~R$0.35/разговор × медиана (socialhub 2026) ≈ R$120 при ~340 разговорах',
};

const STEP_FILES = [
  '01-research.json', '02-framework.json', '03-roadmap.json',
  '04-scoring.json', '05-monetization.json',
];

function main() {
  const run = process.argv[2];
  if (!run) {
    console.error('Usage: node scripts/tag-claims-kind.js output/<run-dir>');
    process.exit(1);
  }

  const seen = new Set();
  let tagged = 0, hinted = 0;

  for (const file of STEP_FILES) {
    const p = path.join(run, file);
    if (!fs.existsSync(p)) {
      console.log(`  skip ${file} (not present)`);
      continue;
    }
    const data = JSON.parse(fs.readFileSync(p, 'utf8'));
    if (!Array.isArray(data.claims) || data.claims.length === 0) continue;

    let changed = false;
    for (const c of data.claims) {
      seen.add(c.id);
      const kind = KIND[c.id];
      if (!kind) {
        console.log(`  ⚠ ${file}: claim "${c.id}" not in KIND map — left untagged (treated as benchmark downstream)`);
        continue;
      }
      if (c.kind !== kind) { c.kind = kind; changed = true; }
      tagged++;
      if (kind === 'metric' && HINT[c.id] && c.collectionHint !== HINT[c.id]) {
        c.collectionHint = HINT[c.id];
        hinted++;
        changed = true;
      }
    }

    if (changed) {
      // ensure_ascii must stay OFF — Cyrillic hints stay readable, not \uXXXX
      fs.writeFileSync(p, JSON.stringify(data, null, 2) + '\n', 'utf8');
      console.log(`  wrote ${file}`);
    } else {
      console.log(`  ${file} already up to date`);
    }
  }

  // surface any map ids that never appeared in the run
  const missing = Object.keys(KIND).filter((id) => !seen.has(id));
  if (missing.length) console.log(`  note: ${missing.length} mapped id(s) not found in run: ${missing.join(', ')}`);

  console.log(`\nDone. Tagged ${tagged} claims, set ${hinted} metric hints.`);
  console.log('Next: node strategy/cli.js render   (then collect-plan to verify the queue)');
}

main();
